const body = $input.first().json.body;

const textMessage = (body.Body || '').trim();
if (!textMessage) return [];

// Phone: Twilio sends "whatsapp:+91XXXXXXXXXX" format
const rawFrom = body.From || '';
const phone = rawFrom.replace('whatsapp:', '').replace('+', '');

if (!phone) return [];

const senderName = body.ProfileName || '';

return [{
  json: {
    phone: phone,
    senderName: senderName,
    clean: textMessage,
    message: textMessage,
    chatId: rawFrom,
    timestamp: new Date().toISOString()
  }
}];

// Check if lead was found; pass through data for next nodes
// Check if lead was found; pass through data for next nodes
const prevData = $('Extract Message Data').first().json
const claudeResponse = $('HTTP Request').first().json;
const airtableResponse = $input.first().json;

const records = airtableResponse.records || [];
const leadExists = records.length > 0;
const lead = leadExists ? records[0] : null;

// Parse Claude extraction
const extractedText = claudeResponse.content[0].text
  .replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
const extracted = JSON.parse(extractedText);

return [{
  json: {
    ...prevData,
    leadExists: leadExists,
    leadId: lead?.id || null,
    leadFields: lead?.fields || {},
    leadName: lead?.fields?.Name || prevData.senderName || 'Buyer',
    bedrooms_wanted: extracted.bedrooms_wanted || null,
    localities_wanted:extracted.localities_wanted || null,
    budget_min:  extracted.budget_min || null,
