// FIX 1 — limit to last 10 messages and strip empty content
const historyRecords = (historyResponse.records || []).reverse().slice(-10);
const conversationHistory = historyRecords.map(r => ({
  role: r.fields.direction === 'inbound' ? 'user' : 'assistant',
  content: r.fields.message || ''
})).filter(m => m.content && m.content.trim() !== '');

// Format properties for the prompt
