// }).join('\n');

// Build lead context — FIX 3: include special_requirements
const lead = messageData.fields;
console.log("hi", lead)
const leadContext = [
  lead.Name ? `Name: ${lead.Name}` : null,
  lead.budget_min || lead.budget_max ? `Budget: ₹${lead.budget_min || '?'}L - ₹${lead.budget_max || '?'}L` : null,
  lead.bedrooms_wanted ? `Looking for: ${lead.bedrooms_wanted}` : null,
