/**

  if (extracted.name && !leadFields.Name) {
  updates.Name = extracted.name;
}
if (extracted.budget_min) updates.budget_min = extracted.budget_min;
if (extracted.budget_max) updates.budget_max = extracted.budget_max;
if (extracted.bedrooms_wanted) updates.bedrooms_wanted = extracted.bedrooms_wanted;
if (extracted.localities_wanted) updates.localities_wanted = extracted.localities_wanted;
if (extracted.special_requirements) {
  updates.special_requirements = extracted.special_requirements;
}
*/
if (data.intent === 'book_visit' && leadFields.status !== 'visit_scheduled') {
  updates.status = 'visit_scheduled';
} else if (data.intent === 'escalate' && leadFields.status !== 'hot') {
  updates.status = 'hot';
} else if (leadFields.status === 'new' && data.intent === 'qualifying') {
  updates.status = 'qualifying';
} else {
  updates.status = 'buy_new'
}

return [{
  json: {
    ...data,
    leadUpdates: updates,
    hasUpdates: Object.keys(updates).length > 0
  }
}];

