// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const d = $input.first().json;

const fields = {};

if (d.bedrooms_wanted)   fields['bedrooms_wanted']   = d.bedrooms_wanted;
if (d.localities_wanted) fields['localities_wanted'] = d.localities_wanted;
if (d.intent)            fields['intent']            = d.intent;
if (d.spl_requests)      fields['spl_requests']      = d.spl_requests;
if (d.budget_min > 0)    fields['budget_min']        = d.budget_min;
if (d.budget_max > 0)    fields['budget_max']        = d.budget_max;

return [{ json: { fields, leadId: d.leadId } }];

